/bin/bash -lc "python3 - <<'PY'
import uno
local_ctx=uno.getComponentContext()
resolver=local_ctx.ServiceManager.createInstanceWithContext('com.sun.star.bridge.UnoUrlResolver', local_ctx)
ctx=resolver.resolve('uno:socket,host=localhost,port=2002;urp;StarOffice.ComponentContext')
desktop=ctx.ServiceManager.createInstanceWithContext('com.sun.star.frame.Desktop', ctx)
en=desktop.getComponents().createEnumeration(); doc=None
while en.hasMoreElements():
    c=en.nextElement()
    try:
        if c.supportsService('com.sun.star.presentation.PresentationDocument') and c.URL.endswith('/38_1.pptx'):
            doc=c; break
    except Exception:
        pass
if doc is None:
    raise SystemExit('presentation not found')

def text_shapes(container):
    for i in range(container.getCount()):
        sh=container.getByIndex(i)
        txt=''
        try:
            txt=sh.getString()
        except Exception:
            txt=''
        if txt.strip():
            yield sh
        try:
            cnt=sh.getCount()
        except Exception:
            cnt=0
        if cnt:
            yield from text_shapes(sh)

def first_text_shape(slide_num):
    page=doc.getDrawPages().getByIndex(slide_num-1)
    return next(text_shapes(page))

# LibreOffice ParagraphAdjust values observed in this document:
# 0=left, 1=right, 3=center.
targets={3:1, 4:3, 5:0}
for slide_num, adjust in targets.items():
    sh=first_text_shape(slide_num)
    cursor=sh.Text.createTextCursor()
    cursor.gotoStart(False)
    cursor.gotoEnd(True)
    cursor.ParaAdjust=adjust
    # Also set without selection so future insertion in the shape inherits the alignment.
    cursor.gotoStart(False)
    cursor.ParaAdjust=adjust
    print(f'slide {slide_num}: {getattr(sh,\"Name\",\"\")} -> ParaAdjust {adjust} text={sh.getString()"'!r}'"')
doc.store()
print('saved')
PY"

